   /**
    * f0 -> PrimaryExpression()
    * f1 -> "."
    * f2 -> Identifier()
    * f3 -> "("
    * f4 -> ( ExpressionList() )?
    * f5 -> ")"
    */
   public R visit(MessageSend n, A argu) {
      R _ret=null;
      R type1 = n.f0.accept(this, argu); 
      if(((String)type1).equals("int[]"))
      {
         System.out.println("Symbol not found");
         System.exit(1);
      }
      n.f1.accept(this, argu);
      inmessage = true;
      n.f2.accept(this, argu);
      inmessage= false;
      n.f3.accept(this, argu);
      n.f4.accept(this, argu);
      n.f5.accept(this, argu);
       if(type1 == INT_R || type1 == BOOLEAN_R || type1 == INT_ARRAY_R||type1 == null){
         System.out.println("Type error");
         System.exit(0);
      }
      String temptype = (type1.toString()).trim();
      if(temptype.charAt(0)=='<'){
         currfuncallname = n.f2.f0.toString();
         if(currfuncallname!=null&&!currfuncallname.equals("apply")){
            System.out.println("Type error");
            System.exit(0);
         }else{
           if(currfunccalltypes!=null&&currfunccalltypes.size()==1&&currfunccalltypes.get(0)!=null&&(currfunccalltypes.get(0)).equals(curr_lambda_info.argtype)){
            _ret = (R) curr_lambda_info.rettype;
           }else{
               System.out.println("Type error");
            System.exit(0);
           }
         }
         currfuncallname = null;
         currfunccalltypes.clear();

      }else{
      currclasscall = type1.toString();
      if(!classesinfoMap.containsKey(currclasscall)){
         System.out.println("Symbol not found");
         System.exit(0);
      }else{
         currfuncallname = n.f2.f0.toString();
         _ret = check_func_call(currclasscall,currfuncallname,currfunccalltypes);
      }
      currclasscall = null;
      currfunccalltypes.clear();
   }
      return _ret;
   }

