   /**
    * f0 -> <IDENTIFIER>
    */
   public R visit(Identifier n, A argu) {
      R _ret=null;
      n.f0.accept(this, argu);
     if(!inmessage&&!in_lambda_argument&&!in_lambda_info){
      if(!in_lambda_expression){
      _ret = check_declaration_error(n.f0.toString(),currclassinfo,currfuninfo);
      }else{
      String curr_var_name = n.f0.toString();
      String curr_lamargtype = new String();
      if(currfuninfo.func_lambdavarinfo.containsKey(curr_lambda_name)){
          NewLambdaType n1 = currfuninfo.func_lambdavarinfo.get(curr_lambda_name);
          curr_lamargtype = n1.argtype;
      }
      if(currclassinfo.class_lambdavarinfo.containsKey(curr_lambda_name)){
         NewLambdaType n1 = currclassinfo.class_lambdavarinfo.get(curr_lambda_name);
         curr_lamargtype = n1.argtype;
      }

      if(curr_var_name.equals(extra_arg)){
         
        _ret = (R)curr_lamargtype;
      }else{
      _ret = check_declaration_error(n.f0.toString(), currclassinfo, currfuninfo);
      }
   }
   String temptype = _ret.toString();
      if(temptype.charAt(0)=='<'){
         curr_lambda_name = n.f0.toString();
          if(currclassinfo.class_funcinfo.get(currfuninfo.name).func_lambdavarinfo.containsKey(curr_lambda_name)){
         curr_lambda_info= currclassinfo.class_funcinfo.get(currfuninfo.name).func_lambdavarinfo.get(curr_lambda_name);
       }else{
         curr_lambda_info = currclassinfo.class_lambdavarinfo.get(curr_lambda_name);
       }
      }
   
     }
      
      return _ret;
   }

